window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-10301\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόσδοτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1783 na letra δ · nº geral 10301</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dado, enviado por Zeus. 〈∆ιός, δίδωμι〉</p></section></article>\n<article id=\"entry-dgp-10302\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοσημεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1784 na letra δ · nº geral 10302</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sinal de Zeus; relâmpago. 〈∆ιός, σημεῖον〉</p></section></article>\n<article id=\"entry-dgp-10303\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιοσκόρειον,</h1><div class=\"entry-meta\"><span>DGP · ordem 1785 na letra δ · nº geral 10303</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ∆ιοσκούρειον, ου (τό) templo dos Dióscuros. 〈∆ιόσκοροι〉</p></section></article>\n<article id=\"entry-dgp-10304\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιόσκοροι,</h1><div class=\"entry-meta\"><span>DGP · ordem 1786 na letra δ · nº geral 10304</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ∆ιόσκουροι, ων (οἱ) os Dióscuros, lit. os rapazes de Zeus, Castor e Pólux. 〈∆ιός, κοῦρος〉</p></section></article>\n<article id=\"entry-dgp-10305\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διότι</h1><div class=\"entry-meta\"><span>DGP · ordem 1787 na letra δ · nº geral 10305</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. 1 (causa) porque ♦ em inter. indir. = δι᾽ ὅτι 2 por que; por qual motivo: φράσω διότι her. direi por que, σκοπεῖν διότι tuc. examinar por que 3 = ὅτι, que. 〈διά, ὅτι〉</p></section></article>\n<article id=\"entry-dgp-10306\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοτρεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1788 na letra δ · nº geral 10306</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nutrido por Zeus; cria de Zeus. 〈∆ιός, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-10307\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διουρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1789 na letra δ · nº geral 10307</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = διορίζω.</p></section></article>\n<article id=\"entry-dgp-10308\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοχλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1790 na letra δ · nº geral 10308</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perturbar; importunar alguém, ac. ou dat. 〈διά, ὀχλέω〉</p></section></article>\n<article id=\"entry-dgp-10309\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίοψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1791 na letra δ · nº geral 10309</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exame; inspeção 2 transparência 3 pers­picácia. 〈διόψομαι〉</p></section></article>\n<article id=\"entry-dgp-10310\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόψομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1792 na letra δ · nº geral 10310</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de διοράω.</p></section></article>\n<article id=\"entry-dgp-10311\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπαις, παιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1793 na letra δ · nº geral 10311</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que tem dois filhos 2 executado por duas crianças. 〈δίς, παῖς〉</p></section></article>\n<article id=\"entry-dgp-10312\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπαλτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1794 na letra δ · nº geral 10312</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 a duas mãos; seguro 2 que brande com as duas mãos, com toda a força; que segura com as duas mãos 3 lançado por duas mãos. 〈δίς, πάλλω〉</p></section></article>\n<article id=\"entry-dgp-10313\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπηχυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 1795 na letra δ · nº geral 10313</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de dois côvados. 〈δίς, πῆχυς〉</p></section></article>\n<article id=\"entry-dgp-10314\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1796 na letra δ · nº geral 10314</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 duplicar 2 intr. ser duplo. 〈δίπλαξ〉</p></section></article>\n<article id=\"entry-dgp-10315\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπλαξ, ακος</h1><div class=\"entry-meta\"><span>DGP · ordem 1797 na letra δ · nº geral 10315</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 disposto em duas camadas; duplo ♦ ἡ δίπλαξ 2 manto duplo. 〈δίς, πλέκω〉</p></section></article>\n<article id=\"entry-dgp-10316\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλασιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1798 na letra δ · nº geral 10316</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διπλασιάσω) 1 duplicar 2 redobrar (uma consoante) 3 intr. ter duas vezes o tamanho; ter o valor redobrado. 〈διπλάσιος〉</p></section></article>\n<article id=\"entry-dgp-10317\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλασιασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1799 na letra δ · nº geral 10317</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de dobrar; duplicação; reduplicação; redobro. 〈διπλασιάζω〉</p></section></article>\n<article id=\"entry-dgp-10318\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλάσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1800 na letra δ · nº geral 10318</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 duplo; duas vezes maior; duas vezes mais numeroso do que, gen. ou com ἤ ♦ ἡ διπλασία 2 o dobro da multa. 〈διπλοῦς〉</p></section></article>\n<article id=\"entry-dgp-10319\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλασιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1801 na letra δ · nº geral 10319</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duplicar. 〈διπλάσιος〉</p></section></article>\n<article id=\"entry-dgp-10320\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλασίων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1802 na letra δ · nº geral 10320</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος = διπλάσιος.</p></section></article>\n<article id=\"entry-dgp-10321\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλασίως</h1><div class=\"entry-meta\"><span>DGP · ordem 1803 na letra δ · nº geral 10321</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. duplamente; duas vezes.</p></section></article>\n<article id=\"entry-dgp-10322\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπλεθρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1804 na letra δ · nº geral 10322</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que mede dois pletros ♦ τὸ δί­πλεθρον 2 espaço de dois pletros. 〈δίς, πλέθρον〉</p></section></article>\n<article id=\"entry-dgp-10323\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 1805 na letra δ · nº geral 10323</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διπλόος.</p></section></article>\n<article id=\"entry-dgp-10324\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλήσιος</h1><div class=\"entry-meta\"><span>DGP · ordem 1806 na letra δ · nº geral 10324</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = διπλάσιος.</p></section></article>\n<article id=\"entry-dgp-10325\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλόη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1807 na letra δ · nº geral 10325</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 linha que divide em dois; rachadura; falha; defeito 2 vício 3 sentido obscuro; ambigüidade 4 Anat. junta do crânio 5 ferrão do escorpião. 〈διπλόος〉</p></section></article>\n<article id=\"entry-dgp-10326\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλοΐζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1808 na letra δ · nº geral 10326</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διπλοίζω dobrar. 〈διπλόος〉</p></section></article>\n<article id=\"entry-dgp-10327\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλόος-οῦς, όη-ῆ, όον-οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 1809 na letra δ · nº geral 10327</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 duplo; que forma duas pregas; dobrado em dois 2 dobrado; curvo 3 de duas partes; duplo; duplicado 4 de natureza dupla; dúbio; ambíguo 5 que acontece duas vezes; repetido 6 que dura duas vezes; duplo 7 Gram. composto ♦ διπλῇ adv. 8 duplamente. 〈δίς, πλόος〉</p></section></article>\n<article id=\"entry-dgp-10328\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλοῦς, ῆ, οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 1810 na letra δ · nº geral 10328</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διπλόος.</p></section></article>\n<article id=\"entry-dgp-10329\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1811 na letra δ · nº geral 10329</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐδίπλωσα) 1 fazer dobras em, dobrar (o manto) 2 multiplicar por dois; duplicar (uma quantidade); redobrar 3 recomeçar (um ato) 4 retribuir 5 repetir; renovar. 〈διπλόος〉</p></section></article>\n<article id=\"entry-dgp-10330\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπλωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1812 na letra δ · nº geral 10330</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quantidade dupla; aquilo que está em dobro 2 aquilo que se divide em dois 3 o que está dobrado em dois (documento) 4 carta; credencial. 〈διπλόω〉</p></section></article>\n<article id=\"entry-dgp-10331\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπλωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1813 na letra δ · nº geral 10331</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Gram. composição 2 duplicação. 〈διπλόω〉</p></section></article>\n<article id=\"entry-dgp-10332\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπόδης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1814 na letra δ · nº geral 10332</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e δίποδος, ου (masc.) que mede dois pés. 〈δίς, πούς〉</p></section></article>\n<article id=\"entry-dgp-10333\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 1815 na letra δ · nº geral 10333</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ποδος 1 que tem dois pés; bípede 2 que mede dois pés ♦ ὁ δίπους 3 gerbo, roedor da Líbia, que salta sobre os dois pés traseiros ♦ τὰ δίποδα 4 os bípedes. 〈δίς, πούς〉</p></section></article>\n<article id=\"entry-dgp-10334\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διπρόσωπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1816 na letra δ · nº geral 10334</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de duas faces; com duas caras 2 de dupla interpretação; ambíguo 3 Gram. que se refere a duas pessoas. 〈δίς, πρόσωπον〉</p></section></article>\n<article id=\"entry-dgp-10335\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπτυχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1817 na letra δ · nº geral 10335</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que forma duas pregas; dobrado 2 duplo 3 pl. dois ♦ δίπτυχα adv. 4 em duas camadas. 〈δίς, πτύσσω〉</p></section></article>\n<article id=\"entry-dgp-10336\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίπυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1818 na letra δ · nº geral 10336</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de duas entradas ♦ τὸ δίπυλον 2 porta dupla. 〈δίς, πύλη〉</p></section></article>\n<article id=\"entry-dgp-10337\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιρκαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1819 na letra δ · nº geral 10337</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Dirce. 〈∆ίρκη〉</p></section></article>\n<article id=\"entry-dgp-10338\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ίρκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1820 na letra δ · nº geral 10338</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Dirce, fonte célebre próxima de Tebas.</p></section></article>\n<article id=\"entry-dgp-10339\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίρρυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1821 na letra δ · nº geral 10339</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com dois timões. 〈δίς, ῥυμός〉</p></section></article>\n<article id=\"entry-dgp-10340\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίς</h1><div class=\"entry-meta\"><span>DGP · ordem 1822 na letra δ · nº geral 10340</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. duas vezes; duplamente.</p></section></article>\n<article id=\"entry-dgp-10341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισθανής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1823 na letra δ · nº geral 10341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">morto duas vezes. 〈δίς, θνῄσκω〉</p></section></article>\n<article id=\"entry-dgp-10342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1824 na letra δ · nº geral 10342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lançar o disco 2 lançar como um disco; lançar. 〈δίσκος〉</p></section></article>\n<article id=\"entry-dgp-10343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίσκηπτρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1825 na letra δ · nº geral 10343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com duplo cetro. 〈δίς, σκῆπτρον〉</p></section></article>\n<article id=\"entry-dgp-10344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισκοβόλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1826 na letra δ · nº geral 10344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançador de disco; discóbolo. 〈δίσκος, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-10345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισκοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1827 na letra δ · nº geral 10345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem a forma de um disco. 〈δίσκος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-10346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισκόραξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1828 na letra δ · nº geral 10346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duplo corvo, em luc. jogo de palavras sobre o nome do retor Córax, por causa de sua rapacidade. 〈δίς, κόραξ〉</p></section></article>\n<article id=\"entry-dgp-10347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίσκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1829 na letra δ · nº geral 10347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disco, chapa redonda para arremesso, usada em atletismo 2 disco (solar ou lunar) 3 prato redondo 4 espelho redondo. 〈δίκω〉</p></section></article>\n<article id=\"entry-dgp-10348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίσκουρα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1830 na letra δ · nº geral 10348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alcance do disco: ἐς δίσκουρα hom. à distância de um lance de disco. 〈δίσκος, οὖρον〉</p></section></article>\n<article id=\"entry-dgp-10349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισκοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1831 na letra δ · nº geral 10349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que traz o disco. 〈δίσκος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-10350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισμυριάς, αδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1832 na letra δ · nº geral 10350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. grupo de vinte mil. 〈δισμύριοι〉</p></section></article>\n<article id=\"entry-dgp-10351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισμύριοι, αι, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1833 na letra δ · nº geral 10351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. vinte mil: ἵππος δισμυρία luc. corpo de 20.000 cavaleiros.</p></section></article>\n<article id=\"entry-dgp-10352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισσάρχης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1834 na letra δ · nº geral 10352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que compartilha o governo com outrem ♦ οἱ δισσάρχαι 2 a dupla de comandantes (Agamenão e Menelau). 〈δισσός, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-10353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισσός,</h1><div class=\"entry-meta\"><span>DGP · ordem 1835 na letra δ · nº geral 10353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. διττός, ή, όν 1 duplo; duplicado 2 pl. dois 3 separado; desunido 4 duvidoso; ambíguo ♦ τὸ δισσόν 5 ambigüidade. 〈δίς〉</p></section></article>\n<article id=\"entry-dgp-10354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισσύλλαβος</h1><div class=\"entry-meta\"><span>DGP · ordem 1836 na letra δ · nº geral 10354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e δισύλλαβος, ος, ον de duas sílabas. 〈δίς, συλλαβή〉</p></section></article>\n<article id=\"entry-dgp-10355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισταγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1837 na letra δ · nº geral 10355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dúvida; incerteza. 〈διστάζω〉</p></section></article>\n<article id=\"entry-dgp-10356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διστάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1838 na letra δ · nº geral 10356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 não crer; duvidar; estar incerto quanto a algo, περί e ac. ou gen., ou com or. (πῶς, πότερον, ὅτι, εἰ ou μή e ind.) ♦ pas. 2 ser objeto de dúvida; ser posto em dúvida; ser duvidoso. 〈δίς, ἵστημι〉</p></section></article>\n<article id=\"entry-dgp-10357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίστιχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1839 na letra δ · nº geral 10357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 disposto em duas fileiras 2 formado de dois versos ♦ τὸ δίστιχον 3 dístico, reunião de um hexâmetro e de um pentâmetro. 〈δίς, στίχος〉</p></section></article>\n<article id=\"entry-dgp-10358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διστοιχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1840 na letra δ · nº geral 10358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fileira dupla. 〈δίς, στοῖχος〉</p></section></article>\n<article id=\"entry-dgp-10359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίστολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1841 na letra δ · nº geral 10359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vai de dois em dois. 〈δίς, στέλλω〉</p></section></article>\n<article id=\"entry-dgp-10360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίστομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1842 na letra δ · nº geral 10360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de duas bocas; de duas entradas ou aberturas (caverna) 2 com dois entroncamentos (estrada) 3 de dois gumes (arma) 4 de duas embocaduras (rio) 5 duvidoso; ambíguo. 〈δίς, στόμα〉</p></section></article>\n<article id=\"entry-dgp-10361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισύλλαβος</h1><div class=\"entry-meta\"><span>DGP · ordem 1843 na letra δ · nº geral 10361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δισσύλλαβος.</p></section></article>\n<article id=\"entry-dgp-10362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισύπατος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1844 na letra δ · nº geral 10362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duas vezes cônsul. 〈δίς, ὕπατος〉</p></section></article>\n<article id=\"entry-dgp-10363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δισχίλιοι, αι, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1845 na letra δ · nº geral 10363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. dois mil.</p></section></article>\n<article id=\"entry-dgp-10364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διτάλαντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1846 na letra δ · nº geral 10364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que pesa dois talentos; que vale dois talentos. 〈δίς, τάλαντον〉</p></section></article>\n<article id=\"entry-dgp-10365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίτονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1847 na letra δ · nº geral 10365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de dois tons. 〈δίς, τόνος〉</p></section></article>\n<article id=\"entry-dgp-10366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διυγιαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1848 na letra δ · nº geral 10366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. διυγιᾶναι) passar sempre bem de saúde. 〈διά, ὑγιαίνω〉</p></section></article>\n<article id=\"entry-dgp-10367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίυγρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1849 na letra δ · nº geral 10367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 úmido; molhado; empapado 2 impregnante. 〈διά, ὑγρός〉</p></section></article>\n<article id=\"entry-dgp-10368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διυλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1850 na letra δ · nº geral 10368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filtrar; purificar. 〈διά, ὑλίζω〉</p></section></article>\n<article id=\"entry-dgp-10369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διυπνίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1851 na letra δ · nº geral 10369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 despertar ♦ méd. 2 acordar. 〈διά, ὑπνίζω〉</p></section></article>\n<article id=\"entry-dgp-10370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διυφαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1852 na letra δ · nº geral 10370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tecer; entrelaçar. 〈διά, ὑφαίνω〉</p></section></article>\n<article id=\"entry-dgp-10371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφάσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1853 na letra δ · nº geral 10371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. 1 duplo; de dois tipos 2 pl. dois. 〈δίς, φημί〉</p></section></article>\n<article id=\"entry-dgp-10372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφάω</h1><div class=\"entry-meta\"><span>DGP · ordem 1854 na letra δ · nº geral 10372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) poét. procurar; andar à procura de; vasculhar.</p></section></article>\n<article id=\"entry-dgp-10373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφθέρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1855 na letra δ · nº geral 10373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele curtida; couro 2 veste de pele 3 tenda de pele 4 saco de pele 5 pele para escrever; pergaminho 6 pl. papéis escritos.</p></section></article>\n<article id=\"entry-dgp-10374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφθερίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1856 na letra δ · nº geral 10374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que traja veste de pele de animal. 〈διφθέρα〉</p></section></article>\n<article id=\"entry-dgp-10375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφθέρινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1857 na letra δ · nº geral 10375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pele; de couro. 〈διφθέρα〉</p></section></article>\n<article id=\"entry-dgp-10376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφρεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1858 na letra δ · nº geral 10376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">condução de um carro. 〈διφρεύω〉</p></section></article>\n<article id=\"entry-dgp-10377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφρευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1859 na letra δ · nº geral 10377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">condutor de carro. 〈διφρεύω〉</p></section></article>\n<article id=\"entry-dgp-10378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1860 na letra δ · nº geral 10378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guiar um carro 2 percorrer de carro. 〈δίφρος〉</p></section></article>\n<article id=\"entry-dgp-10379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφρηλατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1861 na letra δ · nº geral 10379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐδιφρηλάτουν) guiar um carro. 〈διφρηλάτης〉</p></section></article>\n<article id=\"entry-dgp-10380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφρηλάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1862 na letra δ · nº geral 10380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">condutor de carro; cocheiro; auriga. 〈δίφρος, ἐλαύνω〉</p></section></article>\n<article id=\"entry-dgp-10381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίφροντις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1863 na letra δ · nº geral 10381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que tem pensamentos duplos. 〈δίς, φροντίς〉</p></section></article>\n<article id=\"entry-dgp-10382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίφρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1864 na letra δ · nº geral 10382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assento 2 carro 3 sede; trono 4 em Roma, cadeira curul.</p></section></article>\n<article id=\"entry-dgp-10383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφροφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1865 na letra δ · nº geral 10383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 levar um assento ou escabelo 2 levar de carro ♦ pas. 3 fazer-se levar sobre um carro; viajar de carro. 〈διφροφόρος〉</p></section></article>\n<article id=\"entry-dgp-10384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφροφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1866 na letra δ · nº geral 10384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">difróforo, carregador de assento ou de escabelo. 〈δίφρος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-10385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διφυής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1867 na letra δ · nº geral 10385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de dupla natureza ou forma 2 duplo; dúplice 3 pl. dois. 〈δίς, φύω〉</p></section></article>\n<article id=\"entry-dgp-10386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίφυιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1868 na letra δ · nº geral 10386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de dupla natureza 2 pl. dois. 〈διφυής〉</p></section></article>\n<article id=\"entry-dgp-10387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίχα</h1><div class=\"entry-meta\"><span>DGP · ordem 1869 na letra δ · nº geral 10387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em dois; em duas partes; em dois sentidos: τέμνειν δ. plat. dividir em dois, ἐγένοντο δ. αἱ γνῶμαι her. houve opiniões em dois sentidos 2 de modo distinto; separadamente: μαθήσεται ὅσον τό τ᾽ ἄρχειν καὶ τὸ δουλεύειν δ. ésql. aprenderá quanto é diferente ser senhor e ser escravo, οἰκεῖν δ. sóf. habitar separadamente ♦ prep. com gen. 3 à parte de; em separado de: οἷος Ἀτρειδῶν δ. sóf. sozinho, sem os Atridas 4 diferentemente de; contrariamente a: σῆς δ. γνώμης λέγω sóf. falo ao contrário de sua opinião 5 à exceção de: δ. γε ∆ιός ésql. à exceção de Zeus 6 fora de; além de: ἔχεις τι τῶν λελεγμένων δίχα; ésql. sabes algo além do que foi dito?</p></section></article>\n<article id=\"entry-dgp-10388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1870 na letra δ · nº geral 10388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dividir em dois 2 separar; dividir 3 bíbl. indispor alguém, ac., contra outrem, κατά e gen. 〈δίχα〉</p></section></article>\n<article id=\"entry-dgp-10389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχαλός</h1><div class=\"entry-meta\"><span>DGP · ordem 1871 na letra δ · nº geral 10389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. = δίχηλος</p></section></article>\n<article id=\"entry-dgp-10390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 1872 na letra δ · nº geral 10390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em duas partes; em dois 2 de dois modos; duplamente. 〈δίχα〉</p></section></article>\n<article id=\"entry-dgp-10391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίχηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1873 na letra δ · nº geral 10391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem os pés bifendidos; que tem pés de dois cascos 2 de dupla garra; de dupla unha. 〈δίς, χηλή〉</p></section></article>\n<article id=\"entry-dgp-10392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχθά</h1><div class=\"entry-meta\"><span>DGP · ordem 1874 na letra δ · nº geral 10392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. poét. = δίχα.</p></section></article>\n<article id=\"entry-dgp-10393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχθάδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1875 na letra δ · nº geral 10393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dividido em dois 2 duplo ♦ διχ­θάδια adv. 3 em dois. 〈διχθά〉</p></section></article>\n<article id=\"entry-dgp-10394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχογνωμονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1876 na letra δ · nº geral 10394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser de opinião contrária 2 hesitar; duvidar. 〈διχογνώμων〉</p></section></article>\n<article id=\"entry-dgp-10395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχογνώμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1877 na letra δ · nº geral 10395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος hesitante ou indeciso entre duas opiniões. 〈δίχα, γνώμη〉</p></section></article>\n<article id=\"entry-dgp-10396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1878 na letra δ · nº geral 10396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sob dois aspectos; de duas maneiras. 〈δίχα〉</p></section></article>\n<article id=\"entry-dgp-10397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίχολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1879 na letra δ · nº geral 10397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que produz fel por dois órgãos 2 amargo; hostil. 〈δίς, χολή〉</p></section></article>\n<article id=\"entry-dgp-10398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχομηνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1880 na letra δ · nº geral 10398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o primeiro dia da lua cheia, i.e., a metade do mês 2 bíbl. lua cheia. 〈διχόμηνος〉</p></section></article>\n<article id=\"entry-dgp-10399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχόμηνις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1881 na letra δ · nº geral 10399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que divide o mês em duas partes (a lua cheia) 2 que ocorre na época da lua cheia.</p></section></article>\n<article id=\"entry-dgp-10400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διχόμηνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1882 na letra δ · nº geral 10400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da metade do mês; do plenilúnio: σελένη δ. lua da metade do mês, i.e., lua cheia ♦ ἡ διχόμηνος 2 lua cheia. 〈δίχα, μήν〉</p></section></article>\n";
